for c in range(0,6): tiles[1][c]=2
for r in range(1,4): tiles[r][0]=2
for r in range(0,6): tiles[r][2]=3
# intersection overlay: 6 for overlapping colors
for r in range(7):
 for c in range(7):
  if (r==1 and 0<=c<=5) and (c==2 and 0<=r<=5): tiles[r][c]=6
# Expand into cell-grid with 8 separators
out=[]
for tr in range(7):
 for i in range(4):
  row=[]
  for tc in range(7):
   row += [tiles[tr][tc]]*4
   if tc<6: row += [8]
  out.append(row)
  if i==3 and tr<6: out.append([8]*28)
print(len(out),set(map(len,out)))
